css:
:host{
  --bg:var(--lab-canvas);
  --panel:var(--lab-surface);
  --ink:var(--lab-ink);
  --muted:var(--lab-muted);
  --line:var(--lab-line);
  --accent:var(--lab-accent);
  --accent-soft:var(--lab-accent-soft);
  --changed:#fff0c9;

  --fetch:#2f73c5;
  --decode:#a66b27;
  --execute:#2d7a50;

  --address:#7664bb;
  --data:#2f8064;
  --control:#b46c35;
  --clock:var(--lab-accent);

  --cpu-fill:#f8fafb;
  --ram-board:#eaf3ec;
  --ram-chip:#334b3d;
  --contact:#c59a43;
}
*{box-sizing:border-box}
:host{
  margin:0;
  background:var(--lab-canvas);
  color:var(--lab-ink);
  font-family:var(--lab-font-sans);
}

button,select{font:inherit}
button{
  height:34px;
  border:1px solid var(--lab-line);
  border-radius:var(--lab-control-radius);
  background:var(--lab-control,#fff);
  color:var(--lab-ink);
  padding:0 10px;
  cursor:pointer;
  white-space:nowrap;
}
button:hover:not(:disabled){border-color:var(--lab-line-strong,#9eaab4)}
button:disabled{opacity:.45;cursor:not-allowed}
.phase.active.fetch{color:var(--fetch);background:#edf5ff;border-color:#bfd7f1}
.phase.active.decode{color:var(--decode);background:#fff4e7;border-color:#e7ceaa}
.phase.active.execute{color:var(--execute);background:#edf8f1;border-color:#bdddc9}
.cpu-shell{
  grid-area:cpu;
  position:relative;
  min-width:0;
  padding:8px;
}
.cpu-shell::before,.cpu-shell::after{
  content:"";
  position:absolute;
  top:32px;
  bottom:32px;
  width:12px;
  background:repeating-linear-gradient(to bottom,#89959f 0 7px,transparent 7px 16px);
  z-index:0;
}
.cpu-shell::before{left:-4px}
.cpu-shell::after{right:-4px}
.cpu-top-pins,.cpu-bottom-pins{
  position:absolute;
  left:34px;
  right:34px;
  height:12px;
  background:repeating-linear-gradient(to right,#89959f 0 7px,transparent 7px 16px);
  z-index:0;
}
.cpu-top-pins{top:-4px}
.cpu-bottom-pins{bottom:-4px}
.cpu-svg{
  display:block;
  width:100%;
  height:auto;
  border:2px solid #46545f;
  border-radius:13px;
  background:var(--cpu-fill);
  position:relative;
  z-index:1;
}
.cpu-svg .cpu-title{font:800 25px Inter,system-ui,sans-serif;fill:#27333c}
.cpu-svg .box{fill:#fff;stroke:#cbd5dc;stroke-width:2}
.cpu-svg .box.active{fill:var(--accent-soft);stroke:var(--accent);stroke-width:3}
.cpu-svg .box.changed{fill:var(--changed);stroke:#d6ae55;stroke-width:3}
.cpu-svg .logic{fill:#fff;stroke:#9daab4;stroke-width:2.5}
.cpu-svg .logic.active{fill:var(--accent-soft);stroke:var(--accent);stroke-width:3}
.cpu-svg .logic.changed{fill:var(--changed);stroke:#d6ae55;stroke-width:3}
.cpu-svg .reg-name{font:800 14px Inter,system-ui,sans-serif;fill:#53616c}
.cpu-svg .reg-full{font:500 10px Inter,system-ui,sans-serif;fill:#7a8790}
.cpu-svg .reg-value{
  font:800 19px ui-monospace,SFMono-Regular,Menlo,Consolas,monospace;
  fill:#1f2932;
  text-anchor:middle;
}
.cpu-svg .unit-name{font:850 24px Inter,system-ui,sans-serif;fill:#293640;text-anchor:middle}
.cpu-svg .unit-value{
  font:750 13px ui-monospace,SFMono-Regular,Menlo,Consolas,monospace;
  fill:#53616c;
  text-anchor:middle;
}
.cpu-svg .decoder{fill:#fff8f8;stroke:#d49494;stroke-width:1.5}
.cpu-svg .decoder-text{font:800 10px Inter,system-ui,sans-serif;fill:#9d5a5a;text-anchor:middle}

.cpu-svg .data-path{
  fill:none;
  stroke:#b7c1c8;
  stroke-width:2;
  stroke-linecap:round;
  stroke-linejoin:round;
  transition:.14s;
}
.cpu-svg .data-path.active{
  stroke:var(--accent);
  stroke-width:4;
  filter:url(#home-cpu-wireGlow);
  stroke-dasharray:8 7;
  animation:pathFlow .9s linear infinite;
}
.cpu-svg .address-path.active{stroke:var(--address)}
.cpu-svg .system-data-path.active{stroke:var(--data)}
.cpu-svg .system-control-path.active{stroke:var(--control)}

.cpu-svg .control-path{
  fill:none;
  stroke:rgba(180,108,53,.18);
  stroke-width:1.65;
  stroke-dasharray:4 5;
  stroke-linecap:round;
  stroke-linejoin:round;
  transition:.14s;
}
.cpu-svg .control-path.active{
  stroke:var(--control);
  stroke-width:3.1;
  filter:url(#home-cpu-wireGlow);
  stroke-dasharray:7 5;
  animation:pathFlow .9s linear infinite;
}
.cpu-svg .clock-path{
  fill:none;
  stroke:#9ea9b1;
  stroke-width:2;
  stroke-dasharray:3 4;
}
.cpu-svg .clock-path.active{
  stroke:var(--clock);
  stroke-width:3.2;
  filter:url(#home-cpu-wireGlow);
}
@keyframes pathFlow{to{stroke-dashoffset:-30}}
.bus-lane.active .bus-value{opacity:1}
.bus-lane.address.active{color:var(--address)}
.bus-lane.address.active .bus-line{background:var(--address);box-shadow:0 0 10px rgba(118,100,187,.34)}
.bus-lane.address.active .arrow-right{border-left-color:var(--address)}
.bus-lane.data.active{color:var(--data)}
.bus-lane.data.active .bus-line{background:var(--data);box-shadow:0 0 10px rgba(47,128,100,.32)}
.bus-lane.data.active .arrow-right{border-left-color:var(--data)}
.bus-lane.data.active .arrow-left{border-right-color:var(--data)}
.bus-lane.control.active{color:var(--control)}
.bus-lane.control.active .bus-line{background:var(--control);box-shadow:0 0 10px rgba(180,108,53,.32)}
.bus-lane.control.active .arrow-right{border-left-color:var(--control)}
.bus-lane.control.active .arrow-left{border-right-color:var(--control)}
.bus-lane.active .bus-line::after{opacity:1}
@keyframes busRight{from{background-position:0 0}to{background-position:46px 0}}
@keyframes busLeft{from{background-position:46px 0}to{background-position:0 0}}
.ram-row.active{background:var(--accent-soft);box-shadow:inset 4px 0 0 var(--accent)}
.ram-row.changed{background:var(--changed);box-shadow:inset 4px 0 0 #d5a94a}


:host {
  --lab-canvas: #f3f5f7;
  --lab-paper: #fbfbfd;
  --lab-surface: #ffffff;
  --lab-control: #ffffff;
  --lab-ink: #1d1d1f;
  --lab-muted: #6e6e73;
  --lab-line: #d2d2d7;
  --lab-line-strong: #a7a7ad;
  --lab-accent: #5277b8;
  --lab-accent-soft: #eef2fa;
  --lab-good: #18794e;
  --lab-good-soft: #edf8f1;
  --lab-warn: #946200;
  --lab-warn-soft: #fff6e7;
  --lab-bad: #b42318;
  --lab-bad-soft: #fff0ee;
  --lab-focus: #1d1d1f;
  --lab-focus-soft: rgba(29, 29, 31, 0.18);
  --lab-font-sans: -apple-system, BlinkMacSystemFont, "SF Pro Display", "Helvetica Neue", Arial, sans-serif;
  --lab-panel-radius: 12px;
  --lab-control-radius: 8px;
  --lab-pill-radius: 999px;
  --lab-control-height: 35px;
  --lab-panel-shadow: 0 1px 2px rgba(29, 29, 31, 0.04);
  --lab-header-max-width: 1200px;
  --lab-header-gutter: max(28px, calc((100vw - var(--lab-header-max-width)) / 2));
  --lab-page-gutter: var(--lab-header-gutter);
  --lab-compact-workspace-max: 820px;
  --lab-ink-secondary: #424245;
  --lab-surface-muted: #f7f8fa;
  --lab-line-subtle: #e7e8eb;
  --lab-accent-hover: #4569aa;
  --lab-accent-pressed: #3a5d99;
  --lab-accent-surface: #f8fbff;
  --lab-accent-line: #9fb4d6;
  --lab-accent-ink: #315b91;
  --lab-on-accent: #ffffff;
  --lab-needed: #946200;
  --lab-needed-ink: #735100;
  --lab-needed-line: #d8c36a;
  --lab-needed-soft: #fff9db;
  --lab-needed-surface: #fffdf4;
  --lab-good-ink: #225f43;
  --lab-good-line: #9cc7aa;
  --lab-good-surface: #f7fcf8;
  --lab-bad-ink: #8f2f27;
  --lab-bad-line: #d99b93;
  --lab-bad-surface: #fff8f7;
  --lab-type-body: 14px;
  --lab-type-label: 12px;
  --lab-type-annotation: 11px;
  --lab-leading-body: 1.5;
  --lab-action-height: 40px;
  --lab-target-min: 44px;
  --lab-concept-rose: #b85f52;
  --lab-concept-rose-soft: #fff1ef;
  --lab-concept-rose-ink: #8f4439;
  --lab-concept-slate-ink: #34454f;
  --lab-concept-violet: #7563a7;
  --lab-concept-amber: #c9782c;
  --lab-concept-amber-soft: #fff2e6;
  --lab-concept-amber-line: #e0b383;
  --lab-concept-amber-ink: #95571f;
  --lab-drag-halo: drop-shadow(0 0 5px rgba(82, 119, 184, 0.90)) drop-shadow(0 0 10px rgba(82, 119, 184, 0.35));
  --lab-cue-surface: rgba(250, 252, 255, 0.98);
  --lab-cue-copy: #5f7184;
  --lab-shadow-cue: 0 10px 24px rgba(29, 29, 31, 0.16);
  --lab-shadow-phase: 0 12px 30px rgba(29, 29, 31, 0.16);
  --lab-phase-good-surface: rgba(247, 252, 248, 0.99);
}

:host,
:host {
  background: var(--lab-canvas);
}

*,
*::before,
*::after {
  box-sizing: border-box;
}

:host {
  -moz-osx-font-smoothing: grayscale;
  -webkit-font-smoothing: antialiased;
  align-content: start !important;
  font-family: var(--lab-font-sans);
  margin: 0;
  padding-bottom: 0;
  padding-top: 0 !important;
  text-rendering: optimizeLegibility;
}

html[data-theme="dark"],
html[data-theme="dark"] :host {
  background: var(--bg);
}

body[data-lab-layout="compact"] [data-lab-workspace] {
  margin-left: auto;
  margin-right: auto;
  width: min(var(--lab-compact-workspace-max), 100%);
}

:where(button, input, select, textarea, summary):focus-visible {
  outline: 3px solid var(--lab-focus);
  outline-offset: 4px;
}


:host {
  --lab-kit-ink: var(--lab-ink, #20303a);
  --lab-kit-muted: var(--lab-muted, #687780);
  --lab-kit-line: var(--lab-line, #cbd6dc);
  --lab-kit-surface: var(--lab-surface, #ffffff);
  --lab-kit-panel: var(--lab-paper, #f6f9fb);
  --lab-kit-accent: var(--lab-accent, #2b7ac3);
  --lab-kit-accent-soft: var(--lab-accent-soft, #e9f3fb);
  --lab-kit-good: var(--lab-good, #23794d);
  --lab-kit-good-soft: var(--lab-good-soft, #e9f7ef);
  --lab-kit-warn: var(--lab-warn, #8b6419);
  --lab-kit-warn-soft: var(--lab-warn-soft, #fff7d9);
  --lab-kit-bad: var(--lab-bad, #a3443d);
  --lab-kit-bad-soft: var(--lab-bad-soft, #fff0ef);
  --lab-kit-focus: var(--lab-focus, #1f6fb4);
  --lab-kit-focus-ring: rgba(31, 111, 180, .28);
  --lab-kit-canvas: var(--lab-paper, #fbfbfd);
  --lab-kit-canvas-grid: #e7ebee;
  --lab-kit-canvas-grid-size: 24px;
  --lab-kit-radius: var(--lab-panel-radius, 12px);
  --lab-kit-control-radius: var(--lab-control-radius, 8px);
  --lab-kit-shadow: var(--lab-panel-shadow, 0 5px 16px rgba(32, 48, 58, .08));
}
[data-lab-kit-focus]:focus-visible {
  outline: 3px solid var(--lab-kit-focus-ring);
  outline-offset: 2px;
}
.inspector .decision-card.good{border-color:var(--lab-good-line,#9cc7aa);background:var(--lab-good-surface,#f7fcf8)}
.calc-panel .calc-step.good{border-color:var(--lab-good-line,#9cc7aa);background:var(--lab-good-surface,#f7fcf8)}
.calc-panel .calc-step.good::after{color:var(--lab-good-ink,#225f43)}
.lab-activity-bar .run-actions>button.active{background:var(--lab-accent-hover,#4569aa);border-color:var(--lab-accent-hover,#4569aa);color:#fff}
@keyframes workingBorderPulse{0%,100%{border-color:var(--lab-needed-line,#d8c36a);box-shadow:0 0 0 0 rgba(216,195,106,0)}50%{border-color:var(--lab-needed,#946200);box-shadow:0 0 0 3px rgba(216,195,106,.18)}}
@keyframes workingAttention{0%,100%{border-color:var(--lab-needed-line,#d8c36a);box-shadow:none}50%{border-color:var(--lab-needed,#946200);box-shadow:0 0 0 3px rgba(216,195,106,.18)}}
@keyframes workingAttention{0%,100%{border-color:var(--lab-needed-line,#d8c36a);box-shadow:none}50%{border-color:var(--lab-needed,#946200);box-shadow:0 0 0 3px rgba(216,195,106,.18)}}
@keyframes workingAttention{0%,100%{border-color:var(--lab-needed-line,#d8c36a);box-shadow:none}50%{border-color:var(--lab-needed,#946200);box-shadow:0 0 0 3px rgba(216,195,106,.18)}}
@keyframes workingAttention{0%,100%{border-color:var(--lab-needed-line,#d8c36a);box-shadow:none}50%{border-color:var(--lab-needed,#946200);box-shadow:0 0 0 3px rgba(216,195,106,.18)}}
@keyframes workingAttention{0%,100%{border-color:var(--lab-needed-line,#d8c36a);box-shadow:none}50%{border-color:var(--lab-needed,#946200);box-shadow:0 0 0 3px rgba(216,195,106,.18)}}
@keyframes labGuideAttention{0%,100%{box-shadow:0 0 0 4px rgba(82,119,184,.10)}50%{box-shadow:0 0 0 9px rgba(82,119,184,.22)}}
:is(input,textarea,select):focus{outline:none!important;box-shadow:none!important;border-color:var(--lab-field-focus,var(--lab-line-strong,#a7a7ad))!important}
:is(input.good,input.correct){--lab-field-focus:var(--lab-good-ink,#225f43)}
.lab-adopt-v3{color:var(--lab-ink,#1d1d1f)}
.lab-adopt-v3 .panel{border:1px solid var(--lab-line,#d2d2d7);border-radius:12px;background:var(--lab-surface,#fff);box-shadow:none}
.lab-adopt-v3 :is(.mission,.goal-panel).lab-activity-bar{display:flex;align-items:center;justify-content:space-between;flex-wrap:wrap;gap:16px 24px;padding:20px 24px;margin:0;border-bottom-color:var(--lab-line-subtle,#e7e8eb);border-radius:12px 12px 0 0;background:#fff}
.lab-adopt-v3 .lab-activity-bar :is(.goal-top,.goal-meta){display:contents}
.lab-adopt-v3 .lab-activity-bar :is(.mission-copy,.goal-copy){flex:1 1 300px;min-width:0}
.lab-adopt-v3 .lab-activity-bar :is(.mission-copy,.goal-copy)>strong{display:block;font-size:16px;font-weight:400;line-height:1.5;color:var(--lab-accent-ink,#315b91);letter-spacing:normal;text-wrap:balance}
.lab-adopt-v3 .lab-activity-bar :is(.mission-copy,.goal-copy)>span{font-size:12px;font-weight:400;line-height:1.45;color:var(--lab-ink-secondary,#424245)}
.lab-adopt-v3 :is(.setup-meta,.goal-kicker,.step-label,.complexity-help,.calc-badge,.method-badge,.complexity-copy>span,.calc-head>p,.method-head>p){display:none}
.lab-adopt-v3 :is(.mission-actions,.mission-tools,.case-actions){display:flex;align-items:center;flex-wrap:wrap;gap:10px;margin-left:auto}
.lab-adopt-v3 :is(.complexity,.ownership){display:flex;align-items:center;gap:8px;background:transparent;border:0;padding:0;box-shadow:none}
.lab-adopt-v3 :is(.complexity-copy strong,.ownership>span){color:var(--lab-ink,#1d1d1f);font-size:14px;font-weight:400;white-space:nowrap}
.lab-adopt-v3 .lab-activity-bar .lab-toggle{display:inline-flex;flex:none;padding:3px;border:1px solid var(--lab-line,#d2d2d7);border-radius:999px;background:var(--lab-surface-muted,#f7f8fa);box-shadow:0 1px 3px rgba(29,29,31,.08);height:42px;gap:2px}
.lab-adopt-v3 .lab-activity-bar .lab-toggle>button{width:auto;min-height:34px;min-width:40px;padding:0 12px;border:1px solid transparent;border-radius:999px;background:transparent;color:var(--lab-ink-secondary,#424245);font:400 12px/1.2 var(--lab-font-sans,sans-serif);box-shadow:none}
.lab-adopt-v3 .lab-activity-bar .lab-toggle>button[aria-pressed="true"]{background:var(--lab-ink-secondary,#424245);color:#fff}
.lab-adopt-v3 .lab-activity-bar .lab-toggle[data-kind="mode"]>button[aria-pressed="true"]{background:var(--lab-accent-hover,#4569aa);color:#fff}
.lab-adopt-v3 .lab-activity-bar+:is(.lab,.workbench){margin-top:0;border-top:0;border-radius:0 0 12px 12px;padding:20px 24px;position:relative}
.lab-adopt-v3:not(.lab-computing) :is(.workspace,.recurring-workspace){display:grid;grid-template-columns:minmax(0,1fr) minmax(280px,320px);gap:24px;align-items:start}
.lab-adopt-v3 :is(.stage-wrap,.interaction-pane){min-width:0;position:relative}
.lab-adopt-v3 :is(.calc-panel,.method-panel){padding:0 0 0 20px;min-width:0;border:0;border-left:1px solid var(--lab-line-subtle,#e7e8eb);background:transparent}
.lab-adopt-v3 :is(.calc-head,.method-head){padding:0 0 12px;border:0;background:transparent}
.lab-adopt-v3 :is(.calc-head,.method-head) strong{font-size:14px;font-weight:500;color:var(--lab-ink,#1d1d1f)}
.lab-adopt-v3 :is(.calc-flow,.solve-chain){display:grid;gap:10px;margin-top:10px;padding:0}
.lab-adopt-v3 .calc-flow::before,.lab-adopt-v3 .calc-step::before{display:none}
.lab-adopt-v3 :is(.calc-step,.solve-card,.derive-step,.proof-rule,.compare-rule){padding:12px;border:1px solid var(--lab-line-subtle,#e7e8eb);border-radius:8px;background:var(--lab-surface-muted,#f7f8fa);box-shadow:none;opacity:1}
.lab-adopt-v3 :is(.calc-step,.solve-card,.derive-step):has(input:not(:disabled)){border-color:var(--lab-needed-line,#d8c36a);background:var(--lab-needed-surface,#fffdf4)}
.lab-adopt-v3 :is(.calc-step,.solve-card,.derive-step):has(input):is(.good,.complete,.correct),.lab-adopt-v3 :is(.calc-step,.solve-card,.derive-step):has(input.good):not(:has(input:not(.good))){border-color:var(--lab-good-line,#9cc7aa);background:var(--lab-good-surface,#f7fcf8)}
.lab-adopt-v3 :is(.calc-step,.solve-card,.derive-step):has(input):is(.bad,.incorrect),.lab-adopt-v3 :is(.calc-step,.solve-card,.derive-step):has(input.bad,input.incorrect){border-color:var(--lab-bad-line,#d8aaa4);background:var(--lab-bad-surface,#fff8f7)}
.lab-adopt-v3 :is(.calc-step,.solve-card,.derive-step):has(input:not(:disabled)):not(.good,.complete,.correct,.bad,.incorrect):not(:has(input.bad,input.incorrect)):not([data-interacted="true"]){animation:workingAttention 2s ease-in-out infinite}
.lab-adopt-v3 :is(.calc-step,.solve-card,.derive-step):has(input)::after,.lab-adopt-v3 .step-head em{display:none}
.lab-adopt-v3 :is(.step-head span,.solve-card>span,.derive-step-head strong,.calc-label,.reference-strip>span,.solve-label){font-size:12px;line-height:1.45;font-weight:400;text-transform:none;letter-spacing:normal;color:var(--lab-ink-secondary,#424245)}
.lab-adopt-v3 :is(.step-note,.derive-note,.work-feedback,.working-row,.method-panel p,.reference-strip em,.calc-intro,.proof-body,.compare-rule,.gate-caption,.bridge-caption){font-size:14px;font-weight:400;line-height:1.45;color:var(--lab-ink-secondary,#424245)}
.lab-adopt-v3 :is(.step-value,.solve-card>strong,.formula-band,.derive-equation,.calc-equation,.proof-rule code):not(:has(input)){width:fit-content;max-width:100%;padding:3px 7px;border:0;border-radius:4px;background:color-mix(in srgb,var(--lab-concept-violet,#7563a7) 20%,white);color:var(--lab-ink,#1d1d1f);font-size:14px;font-weight:400;line-height:1.45;box-shadow:none;overflow-wrap:anywhere}
.lab-adopt-v3 :is(.reference-strip,.proof-head){padding:12px;border:0;border-radius:8px;background:var(--lab-surface-muted,#f7f8fa);font-size:12px;line-height:1.45}
.lab-adopt-v3 input:not([type="range"]):not([type="checkbox"]):not([type="radio"]){min-height:40px;padding:6px 9px;border-width:1px;border-radius:8px;font-size:14px;font-weight:400;line-height:1.4}
.lab-adopt-v3 :is(input.good,input.correct){border-color:var(--lab-good-line,#9cc7aa);background:var(--lab-good-surface,#f7fcf8)}
.lab-adopt-v3 :is(input.bad,input.incorrect){border-color:var(--lab-bad-line,#d8aaa4);background:var(--lab-bad-surface,#fff8f7)}
.lab-adopt-v3 :is(.solve-arrow,.derive-num){font-size:12px;font-weight:400;color:var(--lab-muted,#6e6e73)}
.lab-adopt-v3 :is(.solve-arrow small,.projection-head span,.visual-copy span,.trace-note){font-size:12px;font-weight:400;line-height:1.45}
.lab-adopt-v3 .lab-action{display:inline-flex;align-items:center;justify-content:center;min-height:40px;padding:8px 14px;border:1px solid var(--lab-accent-line,#9fb4d6);border-radius:8px;background:#fff;color:var(--lab-accent-ink,#315b91);font-size:12px;font-weight:400;line-height:1.3;box-shadow:0 1px 3px rgba(29,29,31,.08)}
